solution:
function solve(start, finish) {
  const aktivitas = start
    .map((s, i) => [s, finish[i]])
    .sort((p, q) => p[1] - q[1])
  let jumlah = 0
  let akhirTerakhir = -Infinity
  for (const [s, f] of aktivitas) {
    if (s >= akhirTerakhir) {
      jumlah++
      akhirTerakhir = f
    }
  }
  return jumlah
}
